/**
 * Game state: the phases, the inputs, and how a game starts.
 *
 * The state is a **discriminated union over `phase`**, not a bag of optional
 * fields. A `ResolvingState` has no `piece`, so nothing can move a piece
 * during a chain; a `FallingState` has no `result`, so nothing can advance a
 * chain while the player is in control. The reducer narrows on `phase` once
 * and hands the narrowed state to a handler typed to accept only that phase —
 * an illegal input in a phase is not ignored at runtime, it does not typecheck.
 *
 * Time is an input. Nothing in this directory reads `Date.now`,
 * `performance.now`, `setTimeout` or `requestAnimationFrame`.
 */

import {
  HEIGHT,
  HIDDEN_ROWS,
  WIDTH,
  createBoard,
  type Board,
  type Color,
  type ResolveResult,
} from '../core/index.js';
import type { Piece } from './piece.js';
import { createQueue, type PieceQueue } from './queue.js';

/** Tunables. Durations are milliseconds of *input* time, never wall clock. */
export interface GameConfig {
  readonly width: number;
  readonly height: number;
  /** Rows at the top that never pop and never form groups. */
  readonly hiddenRows: number;
  /** The column a pair spawns in — the one that decides game over. */
  readonly spawnX: number;
  /** Row of the axis at spawn; the child spawns directly above it. */
  readonly spawnY: number;
  /** Milliseconds per row of natural falling. */
  readonly fallIntervalMs: number;
  /** Grace period between the piece grounding and it locking. 0 = instant. */
  readonly lockDelayMs: number;
  /** Milliseconds each chain step is held before the next one pops. */
  readonly chainStepMs: number;
  /** Pause between a chain finishing and the next pair appearing. */
  readonly spawnDelayMs: number;
}

export const DEFAULT_CONFIG: GameConfig = {
  width: WIDTH,
  height: HEIGHT,
  hiddenRows: HIDDEN_ROWS,
  // Third column, as in the real game. With HIDDEN_ROWS = 1 the axis spawns on
  // the first visible row and the child sits in the hidden row above it.
  spawnX: 2,
  spawnY: HIDDEN_ROWS,
  fallIntervalMs: 800,
  lockDelayMs: 500,
  chainStepMs: 300,
  spawnDelayMs: 0,
};

/** Running totals a UI or a scorer can read off the state. */
export interface Stats {
  readonly piecesPlaced: number;
  /** Number of locks that popped at least one group. */
  readonly chains: number;
  readonly longestChain: number;
  readonly totalCleared: number;
}

export const EMPTY_STATS: Stats = {
  piecesPlaced: 0,
  chains: 0,
  longestChain: 0,
  totalCleared: 0,
};

/** The fields every phase carries. `baseOf` in `step.ts` copies exactly these. */
export interface GameCommon {
  readonly config: GameConfig;
  readonly board: Board;
  readonly queue: PieceQueue;
  /** Sum of every tick fed in so far. Derived from inputs, not from a clock. */
  readonly elapsedMs: number;
  readonly stats: Stats;
  /** The result of the most recent lock, for scoring and rendering. */
  readonly lastResolve: ResolveResult | null;
}

/** Waiting to put the next pair on the board. */
export interface SpawningState extends GameCommon {
  readonly phase: 'spawning';
  /** Milliseconds waited so far, against `config.spawnDelayMs`. */
  readonly sinceMs: number;
}

/** The player is in control and the pair still has room below it. */
export interface FallingState extends GameCommon {
  readonly phase: 'falling';
  readonly piece: Piece;
  /** Milliseconds accumulated toward the next row of natural falling. */
  readonly fallAccMs: number;
}

/** The pair is resting; the player still has `lockDelayMs` to act. */
export interface LockingState extends GameCommon {
  readonly phase: 'locking';
  readonly piece: Piece;
  readonly fallAccMs: number;
  /** Milliseconds accumulated toward locking. */
  readonly lockAccMs: number;
}

/** A chain is playing out, one step at a time. No piece exists. */
export interface ResolvingState extends GameCommon {
  readonly phase: 'resolving';
  readonly result: ResolveResult;
  /** How many of `result.steps` have been shown. `board` matches. */
  readonly stepIndex: number;
  readonly sinceMs: number;
}

export type GameOverReason = 'spawn-blocked';

/** Terminal. Every input is a no-op from here. */
export interface GameOverState extends GameCommon {
  readonly phase: 'gameover';
  readonly reason: GameOverReason;
  /** The pair that could not be placed, for a "you died here" overlay. */
  readonly blockedPiece: Piece;
}

/** The phases in which player actions mean anything. */
export type ControllableState = FallingState | LockingState;

export type GameState =
  | SpawningState
  | FallingState
  | LockingState
  | ResolvingState
  | GameOverState;

/** A slice of elapsed time. The only way the world advances on its own. */
export interface TickInput {
  readonly type: 'tick';
  /** Milliseconds since the last tick. Must be finite and >= 0. */
  readonly ms: number;
}

export type PlayerActionType =
  | 'moveLeft'
  | 'moveRight'
  | 'rotateCW'
  | 'rotateCCW'
  | 'softDrop'
  | 'hardDrop';

export interface PlayerAction {
  readonly type: PlayerActionType;
}

export type Input = TickInput | PlayerAction;

/** `{ type: 'tick', ms }`. */
export function tick(ms: number): TickInput {
  return { type: 'tick', ms };
}

/** `{ type }` for a player action, so tests read as `step(s, action('hardDrop'))`. */
export function action(type: PlayerActionType): PlayerAction {
  return { type };
}

export const MOVE_LEFT: PlayerAction = { type: 'moveLeft' };
export const MOVE_RIGHT: PlayerAction = { type: 'moveRight' };
export const ROTATE_CW: PlayerAction = { type: 'rotateCW' };
export const ROTATE_CCW: PlayerAction = { type: 'rotateCCW' };
export const SOFT_DROP: PlayerAction = { type: 'softDrop' };
export const HARD_DROP: PlayerAction = { type: 'hardDrop' };

export interface NewGameOptions {
  /** Injected randomness for the queue. Required — there is no default. */
  readonly rng: () => number;
  readonly config?: Partial<GameConfig>;
  readonly colors?: readonly Color[];
  readonly previewSize?: number;
  /** Start from an existing board, e.g. a test fixture. Defaults to empty. */
  readonly board?: Board;
}

/**
 * A new game, in the `spawning` phase: the first pair appears on the first
 * tick, because nothing in this module happens without an input.
 */
export function createGame(options: NewGameOptions): SpawningState {
  const config: GameConfig = { ...DEFAULT_CONFIG, ...options.config };
  const board = options.board ?? createBoard(config.width, config.height);
  const queue = createQueue(options.rng, {
    ...(options.colors === undefined ? {} : { colors: options.colors }),
    ...(options.previewSize === undefined ? {} : { previewSize: options.previewSize }),
  });
  return {
    phase: 'spawning',
    config,
    board,
    queue,
    elapsedMs: 0,
    stats: EMPTY_STATS,
    lastResolve: null,
    sinceMs: 0,
  };
}

/** The piece the player controls, if there is one right now. */
export function activePiece(state: GameState): Piece | null {
  return state.phase === 'falling' || state.phase === 'locking' ? state.piece : null;
}

/** Is the game over? */
export function isGameOver(state: GameState): state is GameOverState {
  return state.phase === 'gameover';
}

/**
 * Public surface of the game loop: piece, queue, state and the pure reducer.
 *
 * No clock and no randomness of its own — time arrives as tick inputs and the
 * queue's `rng` is injected by the caller.
 */

export * from './piece.js';
export * from './queue.js';
export * from './rng.js';
export * from './state.js';
export * from './step.js';
/**
 * A seeded pseudo-random generator, so the queue has something to be injected
 * with that is reproducible. Deliberately *not* used by default anywhere:
 * callers pass whatever `() => number` they like. `Math.random` appears
 * nowhere under `src/game/`.
 */

/** mulberry32: small, fast, and identical across runs for the same seed. */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
/**
 * The piece queue.
 *
 * Randomness is **injected**: `createQueue` takes an `rng: () => number`
 * returning values in [0, 1). There is no `Math.random` anywhere under
 * `src/game/` — tests pass a seeded generator (see `rng.ts`).
 *
 * A queue value is an index into a memoised stream of pairs, so `queueTake`
 * is referentially transparent: taking from the same queue value always yields
 * the same pair, however many times the reducer is replayed. The `rng` is
 * consumed once per pair drawn, ever.
 */

import { COLORS, type Color } from '../core/index.js';

/** The two colours of a falling pair: the pivot and the one orbiting it. */
export interface Pair {
  readonly axis: Color;
  readonly child: Color;
}

/** Standard Puyo uses four colours per match, not all five. */
export const DEFAULT_COLORS: readonly Color[] = COLORS.slice(0, 4);

/** How many upcoming pairs a UI can preview by default. */
export const DEFAULT_PREVIEW_SIZE = 2;

/** A lazily generated, memoised, infinite stream of pairs. */
interface PairStream {
  readonly colors: readonly Color[];
  at(index: number): Pair;
}

/** An immutable position in a stream of pairs. */
export interface PieceQueue {
  /** How many pairs have already been taken. */
  readonly index: number;
  /** How many upcoming pairs `upcoming()` returns by default. */
  readonly previewSize: number;
  /** The shared, memoised source. Opaque — compare queues by `index`. */
  readonly stream: PairStream;
}

export interface QueueOptions {
  readonly colors?: readonly Color[];
  readonly previewSize?: number;
}

function createStream(rng: () => number, colors: readonly Color[]): PairStream {
  const cache: Pair[] = [];
  const pick = (): Color => {
    const r = rng();
    if (!Number.isFinite(r) || r < 0 || r >= 1) {
      throw new RangeError(`rng must return a number in [0, 1), got ${r}`);
    }
    return colors[Math.floor(r * colors.length)]!;
  };
  return {
    colors,
    at(index: number): Pair {
      if (!Number.isInteger(index) || index < 0) throw new RangeError(`bad queue index: ${index}`);
      while (cache.length <= index) cache.push({ axis: pick(), child: pick() });
      return cache[index]!;
    },
  };
}

/** A fresh queue drawing from `rng`. */
export function createQueue(rng: () => number, options: QueueOptions = {}): PieceQueue {
  const colors = options.colors ?? DEFAULT_COLORS;
  const previewSize = options.previewSize ?? DEFAULT_PREVIEW_SIZE;
  if (colors.length === 0) throw new RangeError('a queue needs at least one colour');
  if (!Number.isInteger(previewSize) || previewSize < 0) {
    throw new RangeError(`bad previewSize: ${previewSize}`);
  }
  return { index: 0, previewSize, stream: createStream(rng, colors) };
}

/** The pair at the front of `queue`, without taking it. */
export function nextPair(queue: PieceQueue): Pair {
  return queue.stream.at(queue.index);
}

/** The next `count` pairs, front first. For a preview panel. */
export function upcoming(queue: PieceQueue, count: number = queue.previewSize): readonly Pair[] {
  if (!Number.isInteger(count) || count < 0) throw new RangeError(`bad count: ${count}`);
  return Array.from({ length: count }, (_, i) => queue.stream.at(queue.index + i));
}

/** Take the front pair, returning it and the advanced queue. */
export function queueTake(queue: PieceQueue): { readonly pair: Pair; readonly queue: PieceQueue } {
  return { pair: nextPair(queue), queue: { ...queue, index: queue.index + 1 } };
}

/** The colours this queue draws from. */
export function queueColors(queue: PieceQueue): readonly Color[] {
  return queue.stream.colors;
}

/**
 * The falling pair.
 *
 * A piece is two puyos: an **axis** (the pivot) and a **child** that sits in
 * one of four orientations around it. Rotation moves the child around the
 * axis; the axis only moves when a rotation has to kick.
 *
 *   rotation 0        1        2        3
 *      C            A C        A        C A
 *      A                       C
 *
 * Pure data + pure functions. No timers, no randomness, no DOM.
 */

import {
  getCell,
  inBounds,
  setCell,
  type Board,
  type Color,
  type Pos,
} from '../core/index.js';
import type { Pair } from './queue.js';

/** Orientation of the child relative to the axis. 0 = above, then clockwise. */
export type Rotation = 0 | 1 | 2 | 3;

/** All four orientations, in clockwise order. */
export const ROTATIONS: readonly Rotation[] = [0, 1, 2, 3];

/** Where the child sits relative to the axis, per rotation. `y` grows down. */
export const CHILD_OFFSETS: Readonly<Record<Rotation, Pos>> = {
  0: { x: 0, y: -1 },
  1: { x: 1, y: 0 },
  2: { x: 0, y: 1 },
  3: { x: -1, y: 0 },
};

/** Which way a rotation turns. */
export type RotationDirection = 'cw' | 'ccw';

/** A pair of puyos placed on the board at a rotation. */
export interface Piece {
  readonly pair: Pair;
  /** Column of the axis puyo. */
  readonly x: number;
  /** Row of the axis puyo. `y` grows downward. */
  readonly y: number;
  readonly rotation: Rotation;
}

/** One puyo of a piece, with its board position. */
export interface PlacedPuyo {
  readonly x: number;
  readonly y: number;
  readonly color: Color;
  readonly role: 'axis' | 'child';
}

/** Where the child of `piece` sits. May be off the board. */
export function childPos(piece: Piece): Pos {
  const d = CHILD_OFFSETS[piece.rotation];
  return { x: piece.x + d.x, y: piece.y + d.y };
}

/** Both puyos of `piece`, axis first. */
export function pieceCells(piece: Piece): readonly [PlacedPuyo, PlacedPuyo] {
  const child = childPos(piece);
  return [
    { x: piece.x, y: piece.y, color: piece.pair.axis, role: 'axis' },
    { x: child.x, y: child.y, color: piece.pair.child, role: 'child' },
  ];
}

/** Can `piece` occupy its cells: both on the board and both empty? */
export function fits(board: Board, piece: Piece): boolean {
  return pieceCells(piece).every(
    (p) => inBounds(board, p.x, p.y) && getCell(board, p.x, p.y) === null,
  );
}

/** `piece` shifted by (dx, dy), or `null` if that does not fit. */
export function translate(board: Board, piece: Piece, dx: number, dy: number): Piece | null {
  const moved: Piece = { ...piece, x: piece.x + dx, y: piece.y + dy };
  return fits(board, moved) ? moved : null;
}

/** `piece` one row lower, or `null` if it is resting. */
export function moveDown(board: Board, piece: Piece): Piece | null {
  return translate(board, piece, 0, 1);
}

/** Is `piece` resting on the floor or on another puyo? */
export function isGrounded(board: Board, piece: Piece): boolean {
  return moveDown(board, piece) === null;
}

/** The rotation one step `direction` from `rotation`. */
export function turn(rotation: Rotation, direction: RotationDirection): Rotation {
  const delta = direction === 'cw' ? 1 : 3;
  return (((rotation + delta) % 4) as Rotation);
}

/**
 * Rotate `piece`, kicking if the child's target cell is blocked.
 *
 * The kick is a single push of the axis in the direction *opposite* the new
 * child offset — i.e. the pair shoves itself away from whatever is in the way.
 * That one rule covers the wall case (rotating into a side wall walks the pair
 * inward), the floor case (rotating the child downward lifts the pair) and a
 * neighbouring stack. If the kicked position does not fit either, the rotation
 * is **refused** and `null` is returned: no double-kick, no 180° flip.
 */
export function rotate(board: Board, piece: Piece, direction: RotationDirection): Piece | null {
  const rotation = turn(piece.rotation, direction);
  const rotated: Piece = { ...piece, rotation };
  if (fits(board, rotated)) return rotated;

  const d = CHILD_OFFSETS[rotation];
  const kicked: Piece = { ...rotated, x: rotated.x - d.x, y: rotated.y - d.y };
  return fits(board, kicked) ? kicked : null;
}

/** `board` with both puyos of `piece` written into it. Throws if it does not fit. */
export function lockPiece(board: Board, piece: Piece): Board {
  if (!fits(board, piece)) {
    throw new RangeError(`cannot lock piece at (${piece.x}, ${piece.y}) rotation ${piece.rotation}`);
  }
  let next = board;
  for (const p of pieceCells(piece)) next = setCell(next, p.x, p.y, p.color);
  return next;
}

/** The piece a `pair` spawns as: axis in the spawn column, child above it. */
export function spawnPiece(pair: Pair, spawnX: number, spawnY: number): Piece {
  return { pair, x: spawnX, y: spawnY, rotation: 0 };
}
/**
 * The reducer: `step(state, input) -> state`. Pure.
 *
 * Every transition is driven by an input. Ticks carry elapsed milliseconds
 * from outside; nothing here reads a clock or schedules anything.
 *
 * Phase handling is deliberately split into one handler per phase, each typed
 * to accept only the states it applies to. `applyAction` takes a
 * `ControllableState` and a `PlayerAction`, so "rotate during a chain" or
 * "tick handling that assumes a piece" cannot be written, not merely ignored.
 */

import { applyGravity, resolve, type Board } from '../core/index.js';
import {
  fits,
  isGrounded,
  lockPiece,
  moveDown,
  rotate,
  spawnPiece,
  translate,
  type Piece,
} from './piece.js';
import { queueTake } from './queue.js';
import type {
  ControllableState,
  GameCommon,
  FallingState,
  GameOverState,
  GameState,
  Input,
  LockingState,
  PlayerAction,
  ResolvingState,
  SpawningState,
  Stats,
} from './state.js';

/**
 * Advance the game by one input.
 *
 * Player actions only ever reach `applyAction`, which only accepts a
 * controllable (falling/locking) state; ticks are the only thing spawning,
 * resolving and game over react to.
 */
export function step(state: GameState, input: Input): GameState {
  if (input.type === 'tick') {
    const ms = input.ms;
    if (!Number.isFinite(ms) || ms < 0) throw new RangeError(`bad tick ms: ${ms}`);
    const advanced = { ...state, elapsedMs: state.elapsedMs + ms };
    switch (advanced.phase) {
      case 'spawning':
        return tickSpawning(advanced, ms);
      case 'falling':
      case 'locking':
        return tickControllable(advanced, ms);
      case 'resolving':
        return tickResolving(advanced, ms);
      case 'gameover':
        return advanced;
    }
  }
  // `input` is a PlayerAction here, and only a controllable state can act on one.
  switch (state.phase) {
    case 'falling':
    case 'locking':
      return applyAction(state, input);
    case 'spawning':
    case 'resolving':
    case 'gameover':
      return state;
  }
}

/** Run a whole list of inputs, front to back. */
export function stepAll(state: GameState, inputs: readonly Input[]): GameState {
  return inputs.reduce<GameState>(step, state);
}

// ---------------------------------------------------------------- spawning

function tickSpawning(state: SpawningState, ms: number): GameState {
  const sinceMs = state.sinceMs + ms;
  if (sinceMs < state.config.spawnDelayMs) return { ...state, sinceMs };

  const { pair, queue } = queueTake(state.queue);
  const piece = spawnPiece(pair, state.config.spawnX, state.config.spawnY);

  // Game over: the spawn column is blocked. The queue is deliberately *not*
  // advanced, so a UI can still show the pair that had nowhere to go.
  if (!fits(state.board, piece)) {
    const over: GameOverState = {
      ...baseOf(state),
      phase: 'gameover',
      reason: 'spawn-blocked',
      blockedPiece: piece,
    };
    return over;
  }

  const spawned: FallingState = {
    ...baseOf(state),
    phase: 'falling',
    queue,
    piece,
    fallAccMs: 0,
  };
  return spawned;
}

/**
 * The fields every phase shares. Phase transitions copy exactly these and then
 * add the new phase's own fields, rather than spreading the old state whole:
 * spreading would carry the previous phase's fields along as dead properties
 * that the union's types say are not there.
 */
function baseOf(state: GameState): GameCommon {
  const { config, board, queue, elapsedMs, stats, lastResolve } = state;
  return { config, board, queue, elapsedMs, stats, lastResolve };
}

// ------------------------------------------------------------ controllable

function falling(state: ControllableState, piece: Piece, fallAccMs: number): FallingState {
  return { ...baseOf(state), phase: 'falling', piece, fallAccMs };
}

function locking(
  state: ControllableState,
  piece: Piece,
  fallAccMs: number,
  lockAccMs: number,
): LockingState {
  return { ...baseOf(state), phase: 'locking', piece, fallAccMs, lockAccMs };
}

/**
 * Natural gravity, then the lock decision.
 *
 * The lock timer only charges on a tick that begins with the piece already
 * resting, so a piece that grounds *during* this tick gets its full
 * `lockDelayMs` starting from the next one. With `lockDelayMs: 0` that
 * degenerates to locking the moment it grounds.
 */
function tickControllable(state: ControllableState, ms: number): GameState {
  const { fallIntervalMs, lockDelayMs } = state.config;
  const startedGrounded = state.phase === 'locking';
  let piece = state.piece;
  let fallAccMs = state.fallAccMs + ms;

  if (fallIntervalMs > 0) {
    while (fallAccMs >= fallIntervalMs) {
      const moved = moveDown(state.board, piece);
      if (moved === null) break;
      piece = moved;
      fallAccMs -= fallIntervalMs;
    }
  }

  if (!isGrounded(state.board, piece)) return falling(state, piece, fallAccMs);

  const lockAccMs = startedGrounded ? state.lockAccMs + ms : 0;
  if (lockAccMs >= lockDelayMs) return lockAndResolve(state, piece);
  return locking(state, piece, fallAccMs, lockAccMs);
}

/**
 * A player action. Moving or rotating a resting piece does **not** reset the
 * lock timer — it only cancels locking when the piece ends up with room below
 * it again, which is what stops a player stalling forever by spinning in place.
 */
function applyAction(state: ControllableState, input: PlayerAction): GameState {
  const board = state.board;

  switch (input.type) {
    case 'moveLeft':
      return reposition(state, translate(board, state.piece, -1, 0));
    case 'moveRight':
      return reposition(state, translate(board, state.piece, 1, 0));
    case 'rotateCW':
      return reposition(state, rotate(board, state.piece, 'cw'));
    case 'rotateCCW':
      return reposition(state, rotate(board, state.piece, 'ccw'));
    case 'softDrop': {
      // One row down, and the natural-fall accumulator restarts. Resting is a
      // no-op: locking on demand is what hard drop is for.
      return reposition(state, moveDown(board, state.piece), 0);
    }
    case 'hardDrop': {
      let piece = state.piece;
      for (;;) {
        const moved = moveDown(board, piece);
        if (moved === null) break;
        piece = moved;
      }
      return lockAndResolve(state, piece);
    }
  }
}

/** Apply a move that may have been refused (`null` = nothing happens). */
function reposition(
  state: ControllableState,
  moved: Piece | null,
  fallAccMs: number = state.fallAccMs,
): GameState {
  if (moved === null) return state;
  if (isGrounded(state.board, moved)) {
    return locking(state, moved, fallAccMs, state.phase === 'locking' ? state.lockAccMs : 0);
  }
  return falling(state, moved, fallAccMs);
}

// ---------------------------------------------------------------- locking

function lockAndResolve(state: ControllableState, piece: Piece): ResolvingState {
  const placed: Board = lockPiece(state.board, piece);
  const settled = applyGravity(placed);
  const result = resolve(settled, { hiddenRows: state.config.hiddenRows });
  const stats: Stats = { ...state.stats, piecesPlaced: state.stats.piecesPlaced + 1 };

  return {
    ...baseOf(state),
    phase: 'resolving',
    board: settled,
    result,
    stepIndex: 0,
    sinceMs: 0,
    stats,
    lastResolve: result,
  };
}

// -------------------------------------------------------------- resolving

function tickResolving(state: ResolvingState, ms: number): GameState {
  const { chainStepMs } = state.config;
  const steps = state.result.steps;
  let stepIndex = state.stepIndex;
  let sinceMs = state.sinceMs + ms;
  let board = state.board;

  while (stepIndex < steps.length && (chainStepMs <= 0 || sinceMs >= chainStepMs)) {
    board = steps[stepIndex]!.board;
    stepIndex += 1;
    if (chainStepMs > 0) sinceMs -= chainStepMs;
  }

  if (stepIndex < steps.length) return { ...state, board, stepIndex, sinceMs };

  const result = state.result;
  const stats: Stats = {
    ...state.stats,
    chains: state.stats.chains + (result.chainCount > 0 ? 1 : 0),
    longestChain: Math.max(state.stats.longestChain, result.chainCount),
    totalCleared: state.stats.totalCleared + result.totalCleared,
  };
  const spawning: SpawningState = {
    ...baseOf(state),
    phase: 'spawning',
    board: result.board,
    stats,
    sinceMs: 0,
  };
  return spawning;
}

/**
 * Public surface of the pure game core. Everything exported here is
 * side-effect free: no DOM, no canvas, no timers, no randomness.
 */

export * from './board.js';
export * from './text.js';
export * from './gravity.js';
export * from './groups.js';
export * from './resolve.js';
/**
 * Board model.
 *
